// Vectors from playactor: test/remoteplay/crypto/{base,modern}-test.ts and
// registration-test.ts (the latter generated by chiaki), plus the PS5 values
// a script over playactor's own functions prints (vectors.ts, run with
// `npx tsx vectors.ts` against playactor at its ISC-licensed HEAD).

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}

func eqHex(t *testing.T, name string, got []byte, want string) {
	t.Helper()
	if g := hex.EncodeToString(got); g != want {
		t.Errorf("%s:\n got %s\nwant %s", name, g, want)
	}
}

const (
	vecServerNonce = "ae92e764882651ef89018cfa696c6938"
	vecRPKey       = "74a59c9693c2083ba6a84ba050fa8e5a"
	vecRegistKey   = "3031323334353637"
)

func TestGenerateIVPS5(t *testing.T) {
	nonce := unhex(t, "3e7e7a825973adab2f694346bd44dab5")
	eqHex(t, "iv", generateIV(nonce, 0), "9044408273f8044dca767b5a16394d64")
}

func TestPinSeedPS5(t *testing.T) {
	eqHex(t, "seed", pinSeed(78703893, 0x1e), "e29d644c141b9d617431a56d34cfc17f")
}

func TestRegistrationBodyPS5(t *testing.T) {
	nonce := unhex(t, "1337deadbeefc0ffee42636869616b69")
	pin, err := parsePIN("13374201")
	if err != nil {
		t.Fatal(err)
	}
	pc, err := newPinCrypto(pin, nonce)
	if err != nil {
		t.Fatal(err)
	}
	body, err := registrationBody(pc, "AAAAAAAAAEI=")
	if err != nil {
		t.Fatal(err)
	}
	eqHex(t, "body", body, vecRegistrationBody)
}

func TestSessionCryptoPS5(t *testing.T) {
	serverNonce := unhex(t, vecServerNonce)
	rpKey := unhex(t, vecRPKey)

	eqHex(t, "nonce_transform", transformServerNonce(serverNonce), "1cf14bf30a3f0cb37882b417a3557c5f")
	eqHex(t, "auth_seed", authSeed(rpKey, serverNonce), "571cae64db1659b047e0dc7d9739de5a")
	eqHex(t, "iv_c0", generateIV(transformServerNonce(serverNonce), 0), "f16dff5c82ef018d590e35b5518a46ab")
	eqHex(t, "iv_c5", generateIV(transformServerNonce(serverNonce), 5), "5be51e0bdfa4dcdf9376a03e64bb93e6")

	sample := unhex(t, "1337c0ffee00112233445566778899aabbcc")
	sc, err := newSessionCrypto(rpKey, serverNonce)
	if err != nil {
		t.Fatal(err)
	}
	enc0, _ := sc.encrypt(sample)
	enc1, _ := sc.encrypt(sample)
	eqHex(t, "enc_c0", enc0, "e42438c052f89d093cb4a84dde36fd7c2cff")
	eqHex(t, "enc_c1", enc1, "b5ccab703710ff4942f8e6d15fc29f5c5506")

	// The decrypt counter runs separately from the encrypt counter.
	dec, _ := sc.decrypt(unhex(t, "e42438c052f89d093cb4a84dde36fd7c2cff"))
	if !bytes.Equal(dec, sample) {
		t.Errorf("dec_c0 of enc_c0 = %x, want %x", dec, sample)
	}
	peer, _ := newSessionCrypto(rpKey, serverNonce)
	ps5, _ := peer.encrypt([]byte("PS5"))
	fresh, _ := newSessionCrypto(rpKey, serverNonce)
	got, _ := fresh.decrypt(ps5)
	eqHex(t, "dec_c0_of_enc_c0", got, "505335")
}

func TestControlHeadersAndPacketPS5(t *testing.T) {
	sc, err := newSessionCrypto(unhex(t, vecRPKey), unhex(t, vecServerNonce))
	if err != nil {
		t.Fatal(err)
	}
	headers, err := controlHeaders(sc, Registration{RegistKey: vecRegistKey, RPKey: vecRPKey})
	if err != nil {
		t.Fatal(err)
	}
	want := [][2]string{
		{"RP-Auth", "xyLKDIjNuhwP8P0rqb5k1g=="},
		{"RP-Version", "1.0"},
		{"RP-Did", "puNrj9kX7itxPLO3KEoG9ibYarnKXPcX1um0V/fU53Y="},
		{"RP-ControllerType", "3"},
		{"RP-ClientType", "11"},
		{"RP-OSType", "AKa1hSF8HgFk"},
		{"RP-ConPath", "1"},
		{"RP-StartBitrate", "G2Ujnw=="},
		{"RP-StreamingType", "PgRcug=="},
	}
	if len(headers) != len(want) {
		t.Fatalf("got %d headers, want %d", len(headers), len(want))
	}
	for i := range want {
		if headers[i] != want[i] {
			t.Errorf("header %d = %v, want %v", i, headers[i], want[i])
		}
	}

	// The first payload packet after the headers uses encrypt counter 5.
	pkt, err := encodePacket(sc, 0x8004, []byte("1234"))
	if err != nil {
		t.Fatal(err)
	}
	eqHex(t, "pkt_c5", pkt, "0000000480040000129bc17e")

	// Header-only packets go out in the clear and spend no counter.
	pkt, _ = encodePacket(sc, cmdStandby, nil)
	eqHex(t, "standby", pkt, "0000000000500000")
	if sc.encCounter != 6 {
		t.Errorf("encCounter = %d, want 6", sc.encCounter)
	}
}

func TestCredential(t *testing.T) {
	got, err := Registration{RegistKey: vecRegistKey}.Credential()
	if err != nil || got != "19088743" {
		t.Errorf("Credential() = %q, %v; want 19088743", got, err)
	}
	for _, bad := range []string{"", "zz", "7a7a"} { // "7a7a" is "zz": not a hex number
		if _, err := (Registration{RegistKey: bad}).Credential(); err == nil {
			t.Errorf("Credential(%q) succeeded", bad)
		}
	}
}

func TestAccountIDFromUserID(t *testing.T) {
	got, err := AccountIDFromUserID("1234567890123")
	if err != nil || got != "ywT7cR8BAAA=" {
		t.Errorf("AccountIDFromUserID = %q, %v; want ywT7cR8BAAA=", got, err)
	}
	if _, err := AccountIDFromUserID("-1"); err == nil {
		t.Error("negative user ID accepted")
	}
}

func TestNormalizeAccountID(t *testing.T) {
	for in, want := range map[string]string{
		"1234567890123":    "ywT7cR8BAAA=", // numeric PSN user ID
		" ywT7cR8BAAA= \n": "ywT7cR8BAAA=", // base64 as pasted
	} {
		if got, err := NormalizeAccountID(in); err != nil || got != want {
			t.Errorf("NormalizeAccountID(%q) = %q, %v; want %q", in, got, err, want)
		}
	}
	for _, bad := range []string{"", "ywT7cR8B", "AAAAAAAAAAAAAAA=", "not an id"} {
		if got, err := NormalizeAccountID(bad); err == nil {
			t.Errorf("NormalizeAccountID(%q) = %q, want an error", bad, got)
		}
	}
}

func TestRegistrationValid(t *testing.T) {
	cases := []struct {
		reg  Registration
		want bool
	}{
		{Registration{RegistKey: vecRegistKey, RPKey: vecRPKey}, true},
		{Registration{RPKey: vecRPKey}, false},
		{Registration{RegistKey: vecRegistKey, RPKey: vecRPKey[:30]}, false},
		{Registration{RegistKey: vecRegistKey, RPKey: "zz" + vecRPKey[2:]}, false},
	}
	for i, tc := range cases {
		if got := tc.reg.Valid(); got != tc.want {
			t.Errorf("case %d: Valid() = %v, want %v", i, got, tc.want)
		}
	}
}

func TestWakeMessage(t *testing.T) {
	want := "WAKEUP * HTTP/1.1\n" +
		"app-type:r\nauth-type:R\nclient-type:vr\nmodel:w\nuser-credential:19088743\n" +
		"device-discovery-protocol-version:00030010\n"
	if got := string(WakeMessage("19088743")); got != want {
		t.Errorf("WakeMessage:\n%q\nwant\n%q", got, want)
	}
}

func TestParsePIN(t *testing.T) {
	for _, pin := range []string{"", "1234567", "123456789", "1234567a", " 2345678", "+1234567"} {
		if _, err := parsePIN(pin); err == nil {
			t.Errorf("parsePIN(%q) accepted", pin)
		}
	}
	if n, err := parsePIN("00000042"); err != nil || n != 42 {
		t.Errorf("parsePIN(00000042) = %d, %v", n, err)
	}
}

